def darken_hex(hex_color: str, percentage: float) -> str:
    """
    Darken a hex colour by a percentage.

    Args:
        hex_color: Colour such as "#6699CC" or "6699CC".
        percentage: Amount to darken, from 0 to 100.

    Returns:
        The darkened colour as a 6-digit hex string.
    """
    if not 0 <= percentage <= 100:
        raise ValueError("percentage must be between 0 and 100")

    hex_color = hex_color.lstrip("#")

    if len(hex_color) != 6:
        raise ValueError("hex_color must contain exactly 6 hex digits")

    try:
        red, green, blue = (
            int(hex_color[i:i + 2], 16)
            for i in (0, 2, 4)
        )
    except ValueError:
        raise ValueError("hex_color contains invalid characters")

    factor = 1 - percentage / 100

    darkened = (
        round(red * factor),
        round(green * factor),
        round(blue * factor),
    )

    return "#{:02X}{:02X}{:02X}".format(*darkened)


# Example
print(darken_hex("#6699CC", 25))  # #4D7399

from __future__ import annotations

import json
from dataclasses import MISSING, fields, is_dataclass
from typing import Any, TypeVar, get_type_hints


T = TypeVar("T")


class RequestValidationError(ValueError):
    """Raised when a request body cannot be parsed into the requested model."""

    def __init__(self, errors: dict[str, str] | str):
        self.errors = errors
        super().__init__(errors if isinstance(errors, str) else str(errors))


def parse_request_body(body: str | bytes | bytearray | dict[str, Any], model: type[T]) -> T:
    """Parse and validate a request body into a typed dataclass model.

    Args:
        body: JSON text, bytes, or an already-decoded mapping.
        model: A dataclass type to instantiate.

    Returns:
        An instance of ``model``.

    Raises:
        RequestValidationError: If the body is invalid or does not match the model.
        TypeError: If ``model`` is not a dataclass.
    """
    if not is_dataclass(model):
        raise TypeError("model must be a dataclass type")

    data = _decode_body(body)

    if not isinstance(data, dict):
        raise RequestValidationError("request body must be a JSON object")

    hints = get_type_hints(model)
    model_fields = {field.name: field for field in fields(model)}
    errors: dict[str, str] = {}

    unknown_fields = set(data) - set(model_fields)
    for name in sorted(unknown_fields):
        errors[name] = "unexpected field"

    values: dict[str, Any] = {}

    for name, field in model_fields.items():
        if name not in data:
            if field.default is MISSING and field.default_factory is MISSING:
                errors[name] = "field is required"
            continue

        try:
            values[name] = _validate_value(data[name], hints.get(name, field.type), name)
        except RequestValidationError as exc:
            if isinstance(exc.errors, dict):
                errors.update(exc.errors)
            else:
                errors[name] = str(exc)

    if errors:
        raise RequestValidationError(errors)

    try:
        return model(**values)
    except TypeError as exc:
        raise RequestValidationError(str(exc)) from exc


def _decode_body(body: str | bytes | bytearray | dict[str, Any]) -> Any:
    if isinstance(body, dict):
        return body

    if isinstance(body, (bytes, bytearray)):
        try:
            body = body.decode("utf-8")
        except UnicodeDecodeError as exc:
            raise RequestValidationError("request body must be valid UTF-8") from exc

    if not isinstance(body, str):
        raise RequestValidationError("request body must be JSON text or an object")

    try:
        return json.loads(body)
    except json.JSONDecodeError as exc:
        raise RequestValidationError(f"invalid JSON: {exc.msg}") from exc


def _validate_value(value: Any, expected_type: Any, path: str) -> Any:
    from typing import Any as TypingAny, Union, get_args, get_origin
    import types

    if expected_type is TypingAny:
        return value

    origin = get_origin(expected_type)
    args = get_args(expected_type)

    if origin in (Union, types.UnionType):
        errors = []

        for candidate in args:
            if candidate is type(None) and value is None:
                return None

            try:
                return _validate_value(value, candidate, path)
            except RequestValidationError as exc:
                errors.append(str(exc))

        raise RequestValidationError(
            f"{path} has an invalid value for type {expected_type}"
        )

    if value is None:
        raise RequestValidationError(f"{path} must not be null")

    if origin is list:
        if not isinstance(value, list):
            raise RequestValidationError(f"{path} must be a list")

        item_type = args[0] if args else TypingAny
        return [
            _validate_value(item, item_type, f"{path}[{index}]")
            for index, item in enumerate(value)
        ]

    if origin is dict:
        if not isinstance(value, dict):
            raise RequestValidationError(f"{path} must be an object")

        key_type, value_type = args if len(args) == 2 else (TypingAny, TypingAny)
        result = {}

        for key, item in value.items():
            validated_key = _validate_value(key, key_type, f"{path}.<key>")
            result[validated_key] = _validate_value(
                item,
                value_type,
                f"{path}.{key}",
            )

        return result

    if is_dataclass(expected_type):
        if not isinstance(value, dict):
            raise RequestValidationError(f"{path} must be an object")

        return parse_request_body(value, expected_type)

    if expected_type is bool:
        if not isinstance(value, bool):
            raise RequestValidationError(f"{path} must be a boolean")
        return value

    if expected_type is int:
        if isinstance(value, bool) or not isinstance(value, int):
            raise RequestValidationError(f"{path} must be an integer")
        return value

    if expected_type is float:
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise RequestValidationError(f"{path} must be a number")
        return float(value)

    if expected_type is str:
        if not isinstance(value, str):
            raise RequestValidationError(f"{path} must be a string")
        return value

    if isinstance(expected_type, type) and not isinstance(value, expected_type):
        raise RequestValidationError(
            f"{path} must be of type {expected_type.__name__}"
        )

    return value

