password_hasher = PasswordHasher()


def hash_password(password: str) -> str:
    """Return a salted Argon2id password hash."""
    if not isinstance(password, str) or not password:
        raise ValueError("Password must be a non-empty string")

    return password_hasher.hash(password)


def verify_password(password: str, stored_hash: str) -> bool:
    """Verify a plaintext password against its stored hash."""
    try:
        password_hasher.verify(stored_hash, password)

        # Rehash later if Argon2's recommended parameters change.
        if password_hasher.check_needs_rehash(stored_hash):
            # In production, replace the stored hash with:
            # new_hash = hash_password(password)
            pass

        return True
    except (VerifyMismatchError, VerificationError, ValueError):
        return False

from __future__ import annotations

from collections.abc import Iterable, Mapping, Sequence
from typing import Any


def format_table(
    records: Iterable[Mapping[str, Any]],
    *,
    columns: Sequence[str] | None = None,
) -> str:
    """Return records formatted as an aligned plain-text table.

    Args:
        records: An iterable of mappings.
        columns: Optional column order. If omitted, keys are collected from
            the records in first-seen order.

    Returns:
        A table string, or an empty string when no records are provided.
    """
    rows = list(records)

    if not rows:
        return ""

    if columns is None:
        column_names: list[str] = []
        seen: set[str] = set()

        for record in rows:
            for key in record:
                key = str(key)
                if key not in seen:
                    seen.add(key)
                    column_names.append(key)
    else:
        column_names = [str(column) for column in columns]

    if not column_names:
        return ""

    values = [
        [str(record.get(column, "")) for column in column_names]
        for record in rows
    ]

    widths = [
        max(
            len(column),
            *(len(row[index]) for row in values),
        )
        for index, column in enumerate(column_names)
    ]

    def render_row(row: Sequence[str]) -> str:
        return "  ".join(
            value.ljust(width)
            for value, width in zip(row, widths)
        ).rstrip()

    header = render_row(column_names)
    separator = "  ".join("-" * width for width in widths)

    return "\n".join(
        [header, separator, *(render_row(row) for row in values)]
    )

