import re


PHONE_NUMBER_RE = re.compile(r"^\+[1-9]\d{7,14}$")


def format_phone_number(value: str, country_code: str | None = None) -> str:
    """Validate and format a phone number as an international E.164 number.

    Examples:
        format_phone_number("+1 (415) 555-2671") -> "+14155552671"
        format_phone_number("415-555-2671", "1") -> "+14155552671"
    """
    if not isinstance(value, str):
        raise ValueError("phone number must be a string")

    number = value.strip()

    if country_code is not None:
        country_code = re.sub(r"\D", "", country_code)
        if not country_code:
            raise ValueError("country code must contain digits")

        if number.startswith("00"):
            number = number[2:]
        elif number.startswith("+"):
            number = number[1:]
        else:
            number = re.sub(r"\D", "", number)
            number = country_code + number

        number = f"+{number}"
    else:
        number = re.sub(r"[^\d+]", "", number)

        if number.startswith("00"):
            number = f"+{number[2:]}"
        elif not number.startswith("+"):
            raise ValueError(
                "an international number must start with '+' "
                "or provide a country code"
            )

    if not PHONE_NUMBER_RE.fullmatch(number):
        raise ValueError(
            "invalid phone number; expected an international number "
            "with 8 to 15 digits, such as +14155552671"
        )

    return number

from pathlib import Path

def get_env_value(key, default=None, filename=".env"):
    """Return a value from a .env file, or default if missing."""
    path = Path(filename)

    if not path.exists():
        return default

    for line in path.read_text().splitlines():
        line = line.strip()

        if not line or line.startswith("#") or "=" not in line:
            continue

        name, value = line.split("=", 1)
        if name.strip() == key:
            return value.strip().strip('"').strip("'")

    return default


