import re

def format_phone(number: str, country_code: str = "+1") -> str:
    """Validate and format a phone number as +<country code><digits>."""
    digits = re.sub(r"\D", "", number)

    # Remove a leading international dialing prefix, if present.
    if digits.startswith("00"):
        digits = digits[2:]

    # Add the default country code to 10-digit local numbers.
    if len(digits) == 10:
        digits = country_code.lstrip("+") + digits

    if not 11 <= len(digits) <= 15:
        raise ValueError("Invalid phone number length")

    return f"+{digits}"

