import phonenumbers
from phonenumbers import NumberParseException
from phonenumbers.phonenumberutil import PhoneNumberFormat


class InvalidPhoneNumberError(ValueError):
    """Raised when a phone number cannot be parsed or is invalid."""


def format_phone_number(
    phone_number: str,
    default_region: str | None = None,
) -> str:
    """
    Validate and format a phone number in E.164 international format.

    Args:
        phone_number: Phone number such as "+1 415 555 2671".
        default_region: Two-letter region code used for numbers without
            an international country code, such as "US".

    Returns:
        The validated phone number in E.164 format.

    Raises:
        InvalidPhoneNumberError: If the input is empty, malformed, or invalid.
    """
    if not isinstance(phone_number, str) or not phone_number.strip():
        raise InvalidPhoneNumberError("Phone number must be a non-empty string.")

    region = default_region.upper() if default_region else None

    if region is not None and (
        len(region) != 2 or not region.isalpha()
    ):
        raise InvalidPhoneNumberError(
            "default_region must be a two-letter country code."
        )

    try:
        parsed_number = phonenumbers.parse(phone_number.strip(), region)
    except NumberParseException as exc:
        raise InvalidPhoneNumberError(
            "Phone number could not be parsed."
        ) from exc

    if not phonenumbers.is_possible_number(parsed_number):
        raise InvalidPhoneNumberError("Phone number is not possible.")

    if not phonenumbers.is_valid_number(parsed_number):
        raise InvalidPhoneNumberError("Phone number is not valid.")

    return phonenumbers.format_number(
        parsed_number,
        PhoneNumberFormat.E164,
    )

