from difflib import SequenceMatcher


def closest_name(query: str, names: list[str]) -> str | None:
    """Return the name most similar to query, or None for an empty list."""
    if not names:
        return None

    query = query.strip().casefold()

    return max(
        names,
        key=lambda name: SequenceMatcher(
            None,
            query,
            name.strip().casefold(),
        ).ratio(),
    )

import time
from functools import wraps

def ttl_cache(seconds):
    def decorator(func):
        cache = {}

        @wraps(func)
        def wrapper(*args, **kwargs):
            key = (args, tuple(sorted(kwargs.items())))
            now = time.monotonic()

            if key in cache:
                value, timestamp = cache[key]
                if now - timestamp < seconds:
                    return value

            value = func(*args, **kwargs)
            cache[key] = (value, now)
            return value

        return wrapper
    return decorator


@ttl_cache(seconds=60)
