import phonenumbers
from phonenumbers import NumberParseException
from phonenumbers import PhoneNumberFormat

def normalize_phone(value: str, default_region: str = "US") -> str | None:
    """
    Return an E.164 phone number, or None if invalid.

    default_region is used when value does not include a country code.
    """
    try:
        number = phonenumbers.parse(value, default_region)

        if not phonenumbers.is_possible_number(number):
            return None

        if not phonenumbers.is_valid_number(number):
            return None

        return phonenumbers.format_number(
            number,
            PhoneNumberFormat.E164
        )

    except NumberParseException:
        return None

def normalize_international_phone(value: str) -> str | None:
    try:
        number = phonenumbers.parse(value, None)

        if not phonenumbers.is_valid_number(number):
            return None

        return phonenumbers.format_number(
            number,
            phonenumbers.PhoneNumberFormat.E164
        )
    except NumberParseException:
        return None

