from dataclasses import MISSING, fields, is_dataclass
from enum import Enum
from types import UnionType
from typing import Any, TypeVar, Union, get_args, get_origin, get_type_hints


T = TypeVar("T")


class RequestBodyError(ValueError):
    """Raised when a request body cannot be parsed into the requested model."""


def parse_request_body(body: Any, model: type[T]) -> T:
    """Validate and convert a mapping into a typed dataclass instance.

    Args:
        body: Request body, normally decoded from JSON.
        model: A dataclass type describing the expected body.

    Returns:
        An instance of ``model``.

    Raises:
        RequestBodyError: If the body is malformed or fails validation.

    Example:
        >>> from dataclasses import dataclass
        >>> @dataclass
        ... class CreateUser:
        ...     name: str
        ...     age: int
        >>> parse_request_body({"name": "Ada", "age": 36}, CreateUser)
        CreateUser(name='Ada', age=36)
    """
    if not is_dataclass(model) or isinstance(model, type) is False:
        raise TypeError("model must be a dataclass type")

    if not isinstance(body, dict):
        raise RequestBodyError("request body must be a JSON object")

    try:
        return _parse_value(body, model, "$")
    except RequestBodyError:
        raise
    except Exception as exc:
        raise RequestBodyError(f"invalid request body: {exc}") from exc


def _parse_value(value: Any, expected: Any, path: str) -> Any:
    origin = get_origin(expected)
    args = get_args(expected)

    if expected is Any:
        return value

    if origin in (Union, UnionType):
        if value is None and type(None) in args:
            return None

        errors = []
        for option in args:
            if option is type(None):
                continue
            try:
                return _parse_value(value, option, path)
            except RequestBodyError as exc:
                errors.append(str(exc))

        raise RequestBodyError(
            f"{path}: value does not match any allowed type"
        )

    if value is None:
        raise RequestBodyError(f"{path}: value is required")

    if is_dataclass(expected):
        if not isinstance(value, dict):
            raise RequestBodyError(f"{path}: expected an object")

        hints = get_type_hints(expected)
        known_fields = {field.name for field in fields(expected)}
        unknown = set(value) - known_fields

        if unknown:
            names = ", ".join(sorted(unknown))
            raise RequestBodyError(f"{path}: unexpected field(s): {names}")

        parsed = {}

        for field in fields(expected):
            field_path = f"{path}.{field.name}"
            if field.name not in value:
                if field.default is not MISSING or field.default_factory is not MISSING:
                    continue
                raise RequestBodyError(f"{field_path}: field is required")

            parsed[field.name] = _parse_value(
                value[field.name],
                hints.get(field.name, field.type),
                field_path,
            )

        return expected(**parsed)

    if origin is list:
        if not isinstance(value, list):
            raise RequestBodyError(f"{path}: expected a list")

        item_type = args[0] if args else Any
        return [
            _parse_value(item, item_type, f"{path}[{index}]")
            for index, item in enumerate(value)
        ]

    if origin is dict:
        if not isinstance(value, dict):
            raise RequestBodyError(f"{path}: expected an object")

        key_type, value_type = args or (Any, Any)
        return {
            _parse_value(key, key_type, f"{path}.<key>"):
            _parse_value(item, value_type, f"{path}.{key!s}")
            for key, item in value.items()
        }

    if isinstance(expected, type) and issubclass(expected, Enum):
        try:
            return expected(value)
        except ValueError as exc:
            allowed = ", ".join(repr(item.value) for item in expected)
            raise RequestBodyError(
                f"{path}: expected one of {allowed}"
            ) from exc

    if expected is bool:
        if not isinstance(value, bool):
            raise RequestBodyError(f"{path}: expected a boolean")
        return value

    if expected is int:
        if isinstance(value, bool) or not isinstance(value, int):
            raise RequestBodyError(f"{path}: expected an integer")
        return value

    if expected is float:
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise RequestBodyError(f"{path}: expected a number")
        return float(value)

    if expected is str:
        if not isinstance(value, str):
            raise RequestBodyError(f"{path}: expected a string")
        return value

    if isinstance(expected, type) and not isinstance(value, expected):
        raise RequestBodyError(
            f"{path}: expected {expected.__name__}"
        )

    return value

