from pydantic import BaseModel, ValidationError

ModelT = TypeVar("ModelT", bound=BaseModel)


def parse_request_body(
    body: Any,
    model: type[ModelT],
) -> ModelT:
    """
    Parse and validate a request body into a typed Pydantic model.

    Raises:
        TypeError: If `model` is not a Pydantic model class.
        ValidationError: If the request body is invalid.
    """
    if not isinstance(model, type) or not issubclass(model, BaseModel):
        raise TypeError("model must be a Pydantic BaseModel subclass")

    if not isinstance(body, Mapping):
        raise ValidationError.from_exception_data(
            title=model.__name__,
            line_errors=[
                {
                    "type": "model_type",
                    "loc": (),
                    "input": body,
                    "ctx": {"class_name": model.__name__},
                }
            ],
        )

    return model.model_validate(body)

