from pathlib import Path
import os


def get_env_value(
    key: str,
    default: str | None = None,
    env_file: str | Path = ".env",
) -> str | None:
    """Return an environment value, falling back to a value in a .env file.

    Existing process environment variables take precedence over values in
    the .env file. Missing keys return ``default``.
    """
    value = os.getenv(key)
    if value is not None:
        return value

    path = Path(env_file)
    if not path.is_file():
        return default

    try:
        lines = path.read_text(encoding="utf-8").splitlines()
    except OSError:
        return default

    for line in lines:
        line = line.strip()

        if not line or line.startswith("#") or "=" not in line:
            continue

        name, file_value = line.split("=", 1)
        name = name.strip()

        if name != key:
            continue

        file_value = file_value.strip()

        # Support optional single- or double-quoted values.
        if len(file_value) >= 2 and file_value[0] == file_value[-1]:
            if file_value[0] in {"'", '"'}:
                file_value = file_value[1:-1]

        return file_value

    return default

