import phonenumbers
from phonenumbers import NumberParseException, PhoneNumberFormat


def format_phone_number(phone: str, default_region: str | None = None) -> str:
    """
    Validate and format a phone number as E.164 international format.

    Examples:
        format_phone_number("(415) 555-2671", "US")
        # "+14155552671"

        format_phone_number("+44 20 7946 0958")
        # "+442079460958"

    Args:
        phone: Phone number, optionally including a country code.
        default_region: Two-letter ISO country code used when `phone`
                        does not include a country code, e.g. "US".

    Raises:
        ValueError: If the number is missing, malformed, or invalid.
    """
    if not isinstance(phone, str) or not phone.strip():
        raise ValueError("Phone number must be a non-empty string.")

    try:
        parsed = phonenumbers.parse(phone.strip(), default_region)
    except NumberParseException as exc:
        raise ValueError(f"Invalid phone number: {exc}") from exc

    if not phonenumbers.is_valid_number(parsed):
        raise ValueError("Phone number is not valid.")

    return phonenumbers.format_number(parsed, PhoneNumberFormat.E164)


