from collections.abc import Iterable, Mapping, Sequence
from typing import Any


def print_table(
    records: Iterable[Mapping[str, Any] | Sequence[Any]],
    headers: Sequence[str] | None = None,
) -> None:
    """Print records as an aligned table.

    Records may be mappings or sequences. For mappings, headers are inferred
    from the first record unless explicitly provided.
    """
    rows = list(records)

    if not rows:
        print("(no records)")
        return

    if headers is None:
        first = rows[0]
        if isinstance(first, Mapping):
            headers = list(first.keys())
        else:
            headers = [f"Column {index + 1}" for index in range(len(first))]

    header_list = [str(header) for header in headers]
    table_rows: list[list[str]] = []

    for record in rows:
        if isinstance(record, Mapping):
            values = [record.get(header, "") for header in headers]
        else:
            values = list(record)

        table_rows.append([str(value) if value is not None else "" for value in values])

    widths = [
        max(
            len(header_list[index]),
            *(len(row[index]) if index < len(row) else 0 for row in table_rows),
        )
        for index in range(len(header_list))
    ]

    def format_row(row: Sequence[str]) -> str:
        cells = [
            row[index].ljust(widths[index]) if index < len(row) else " " * widths[index]
            for index in range(len(widths))
        ]
        return " | ".join(cells)

    separator = "-+-".join("-" * width for width in widths)

    print(format_row(header_list))
    print(separator)

    for row in table_rows:
        print(format_row(row))

def print_table(records, headers):
    rows = [headers] + [[str(value) for value in record] for record in records]

    widths = [
        max(len(row[i]) for row in rows)
        for i in range(len(headers))
    ]

    def format_row(row):
        return "  ".join(
            f"{value:<{widths[i]}}" for i, value in enumerate(row)
        )

    print(format_row(headers))
    print("  ".join("-" * width for width in widths))

    for record in records:
        print(format_row([str(value) for value in record]))


