from difflib import SequenceMatcher
from typing import Iterable

from fastapi import FastAPI, HTTPException
from pydantic import BaseModel, Field

app = FastAPI(title="DataPipeline API")


class MatchRequest(BaseModel):
    query: str = Field(..., min_length=1)
    names: list[str] = Field(..., min_length=1)


class MatchResponse(BaseModel):
    query: str
    match: str
    score: float


def closest_match(query: str, names: Iterable[str]) -> tuple[str, float]:
    """Return the name most similar to query and its similarity score."""
    candidates = [name for name in names if name.strip()]

    if not candidates:
        raise ValueError("names must contain at least one non-empty value")

    normalized_query = query.strip().casefold()

    scored = [
        (
            name,
            SequenceMatcher(
                None,
                normalized_query,
                name.strip().casefold(),
            ).ratio(),
        )
        for name in candidates
    ]

    # max() preserves the first item when scores are tied.
    return max(scored, key=lambda item: item[1])


@app.post("/match", response_model=MatchResponse)
def find_closest_match(request: MatchRequest) -> MatchResponse:
    try:
        match, score = closest_match(request.query, request.names)
    except ValueError as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc

    return MatchResponse(
        query=request.query,
        match=match,
        score=round(score, 4),
    )

