from __future__ import annotations

from collections.abc import Callable
from functools import wraps
from threading import RLock
from time import monotonic
from typing import Any, ParamSpec, TypeVar

P = ParamSpec("P")
R = TypeVar("R")


def ttl_cache(
    ttl: float,
) -> Callable[[Callable[P, R]], Callable[P, R]]:
    """Cache function results for ``ttl`` seconds.

    Results are cached by positional and keyword arguments. Exceptions are
    not cached. A non-positive TTL disables caching.

    Example:
        @ttl_cache(60)
        def fetch_data(url: str) -> dict:
            ...
    """
    if ttl < 0:
        raise ValueError("ttl must be non-negative")

    def decorator(function: Callable[P, R]) -> Callable[P, R]:
        cache: dict[tuple[Any, ...], tuple[float, R]] = {}
        lock = RLock()

        def make_key(args: tuple[Any, ...], kwargs: dict[str, Any]) -> tuple[Any, ...]:
            # Sorting makes calls with equivalent keyword arguments share a cache entry.
            return args + (object(),) + tuple(sorted(kwargs.items()))

        @wraps(function)
        def wrapper(*args: P.args, **kwargs: P.kwargs) -> R:
            if ttl == 0:
                return function(*args, **kwargs)

            key = make_key(args, kwargs)
            now = monotonic()

            with lock:
                cached = cache.get(key)
                if cached is not None:
                    created_at, value = cached
                    if now - created_at < ttl:
                        return value
                    del cache[key]

            value = function(*args, **kwargs)

            with lock:
                cache[key] = (monotonic(), value)

            return value

        def cache_clear() -> None:
            """Remove all cached results."""
            with lock:
                cache.clear()

        wrapper.cache_clear = cache_clear  # type: ignore[attr-defined]
        return wrapper

    return decorator

