import time
from functools import wraps

def ttl_cache(ttl_seconds):
    def decorator(func):
        cache = {}

        @wraps(func)
        def wrapper(*args, **kwargs):
            key = (args, tuple(sorted(kwargs.items())))
            now = time.monotonic()

            if key in cache:
                value, expires_at = cache[key]
                if now < expires_at:
                    return value
                del cache[key]

            value = func(*args, **kwargs)
            cache[key] = (value, now + ttl_seconds)
            return value

        wrapper.cache_clear = cache.clear
        return wrapper

    return decorator

@ttl_cache(300)
def expensive_function(x):
    return x * x

from __future__ import annotations

import os
from pathlib import Path


def read_env_value(
    key: str,
    default: str | None = None,
    env_file: str | Path = ".env",
) -> str | None:
    """Return a value from a .env file, falling back to the process environment.

    The process environment takes precedence over values in the .env file.
    Missing keys return ``default``.
    """
    if key in os.environ:
        return os.environ[key]

    path = Path(env_file)

    try:
        lines = path.read_text(encoding="utf-8").splitlines()
    except FileNotFoundError:
        return default

    for line in lines:
        line = line.strip()

        if not line or line.startswith("#"):
            continue

        if line.startswith("export "):
            line = line[7:].lstrip()

        if "=" not in line:
            continue

        name, value = line.split("=", 1)

        if name.strip() != key:
            continue

        value = value.strip()

        if len(value) >= 2 and value[0] == value[-1] and value[0] in {"'", '"'}:
            value = value[1:-1]

        return value

    return default
